with enriched as (select a.*, o.status, o.amount from order_items a left join orders o on a.order_id = o.id) select status, sum(case when status = 'RETURNED' then amount else 0 end) as returned_amount, round(sum(amount) / nullif(count(case when status = 'CANCELLED' then 1 end), 0), 2) as amount_per_cancelled, count(*) as cnt, min(unit_price) as min_unit_price from enriched group by status having min(unit_price) < 0;
